def solve2(g):
    H,W=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r); bg=cnt.most_common(1)[0][0]
    br=[r for r in range(H) if all(x==2 for x in g[r])]
    bc=[c for c in range(W) if all(g[r][c]==2 for r in range(H))]
    vertical=bool(br)
    barmid = bc[0] if not vertical else br[0]
    seen=set(); comps=[]
    for r in range(H):
        for c in range(W):
            if g[r][c] not in (bg,2) and (r,c) not in seen:
                st=[(r,c)]; seen.add((r,c)); comp=[]
                while st:
                    q=st.pop(); comp.append(q)
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=q[0]+dr,q[1]+dc
                        if 0<=a<H and 0<=b<W and g[a][b] not in (bg,2) and (a,b) not in seen:
                            seen.add((a,b)); st.append((a,b))
                comps.append(comp)
    out=[row[:] for row in g]
    for comp in comps:
        rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
        if vertical:
            sgn=-1 if barmid>max(cs) else 1
            touched=any(abs(c-barmid)<=1 for _,c in comp)
            if sgn==0 or touched: continue
            best=None; k=1
            while True:
                okk=True; n=k
                while n<k:
                    r,c=comp[n]
                    t=r,c+k*sgn
                    if not (0<=t[1]<W) or g[t[0]][t[1]]!=bg: okk=False;break
                    n+=1
                if okk: best=k;k+=1
                else: break
            k=best if best else 1
            ns={(r,c+k*sgn) for r,c in comp}
            fl=max(c for _,c in ns)+sgn
            for r in range(H):
                if 0<=fl<W and g[r][fl]==bg: out[r][fl]=8
            for r,c in ns: out[r][c]=g[r][c]
        else:
            sgn=-1 if barmid>min(rs) else 1
            touched=any(abs(r-barmid)<=1 for r,_ in comp)
            if sgn==0 or touched: continue
            best=None; k=1
            while True:
                okk=True; n=k
                while n<k:
                    r,c=comp[n]
                    t=r+k*sgn,c
                    if not (0<=t[0]<H) or g[t[0]][c]!=bg: okk=False;break
                    n+=1
                if okk: best=k;k+=1
                else: break
            k=best if best else 1
            ns={(r+k*sgn,c) for r,c in comp}
            fr=min(r for r,_ in ns)+sgn
            fc=max(c for _,c in ns)+(-sgn)
            for c in range(W):
                if 0<=fc<W and g[fr][fc]==bg: out[fr][fc]=8
            for r,c in ns: out[r][c]=g[r][c]
    return out

